// A knob on A0 sets the brightness of an LED on D9
const int LED_PIN = 9;     // D9 = PC7, PWM from timer TIM3
const int KNOB_PIN = A0;

void setup() {
  pinMode(LED_PIN, OUTPUT);
  analogReadResolution(12);  // 0..4095
  Serial.begin(115200);
}

void loop() {
  int raw = analogRead(KNOB_PIN);
  int duty = map(raw, 0, 4095, 0, 255);  // 0..4095 in, 0..255 duty out
  analogWrite(LED_PIN, duty);
  Serial.print("raw=");
  Serial.print(raw);
  Serial.print(" duty=");
  Serial.println(duty);
  delay({{p:period}});
}

